    v_updated := v_updated + 1;
  end if;

  select count(*) into v_total from public.academy_quiz_questions where app_slug = 'casingtubing';
  if v_total <> 396 then raise exception 'answer-length recut, casingtubing refused: the course holds % questions, expected 396', v_total; end if;
  raise notice 'answer-length recut, casingtubing: % of 207 rows updated, the rest already carried the recut text', v_updated;
end $$;
